"use server";

import { createAdminClient } from "@/lib/appwrite";
import { appwriteConfig } from "@/lib/appwrite/config";
import { ID, Query } from "node-appwrite";
import { parseStringify } from "@/lib/utils";
import { revalidatePath } from "next/cache";
import { getCurrentUser } from "@/lib/actions/user.actions";

interface CreateFolderProps {
  name: string;
  parentId?: string;
  path: string;
}

interface GetFoldersProps {
  parentId?: string;
  searchText?: string;
  sort?: string;
}

const handleError = (error: unknown, message: string) => {
  console.log(error, message);
  throw error;
};

export const createFolder = async ({ name, parentId, path }: CreateFolderProps) => {
  const { databases } = await createAdminClient();
  const currentUser = await getCurrentUser();

  if (!currentUser) throw new Error("User not found");

  try {
    const folderDocument = {
      name,
      parentId: parentId || null,
      owner: currentUser.$id,
      path: parentId ? `${parentId}/${name}` : name,
    };

    const newFolder = await databases.createDocument(
      appwriteConfig.databaseId,
      appwriteConfig.foldersCollectionId,
      ID.unique(),
      folderDocument,
    );

    revalidatePath(path);
    return parseStringify(newFolder);
  } catch (error) {
    handleError(error, "Failed to create folder");
  }
};

export const getFolders = async ({ parentId, searchText = "", sort = "$createdAt-desc" }: GetFoldersProps) => {
  const { databases } = await createAdminClient();
  const currentUser = await getCurrentUser();

  if (!currentUser) throw new Error("User not found");

  try {
    const queries = [
      Query.equal("owner", [currentUser.$id]),
    ];

    if (parentId) {
      queries.push(Query.equal("parentId", [parentId]));
    } else {
      queries.push(Query.equal("parentId", [null]));
    }

    if (searchText) {
      queries.push(Query.contains("name", searchText));
    }

    const [sortBy, orderBy] = sort.split("-");
    queries.push(
      orderBy === "asc" ? Query.orderAsc(sortBy) : Query.orderDesc(sortBy),
    );

    const folders = await databases.listDocuments(
      appwriteConfig.databaseId,
      appwriteConfig.foldersCollectionId,
      queries,
    );

    return parseStringify(folders);
  } catch (error) {
    handleError(error, "Failed to get folders");
  }
};

export const deleteFolder = async (folderId: string, path: string) => {
  const { databases } = await createAdminClient();

  try {
    // Delete the folder
    await databases.deleteDocument(
      appwriteConfig.databaseId,
      appwriteConfig.foldersCollectionId,
      folderId
    );

    revalidatePath(path);
    return { success: true };
  } catch (error) {
    handleError(error, "Failed to delete folder");
  }
};
